import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import { build } from 'esbuild';
import { chromium } from 'playwright';

const input = JSON.parse(await readFile(process.env.EVALUATION_INPUT, 'utf8'));
await build({
  stdin: { contents: `import Papa from 'papaparse'; document.querySelector('button').onclick=()=>{const parsed=Papa.parse(document.querySelector('textarea').value,{header:true,skipEmptyLines:true}); document.querySelector('pre').textContent=JSON.stringify(parsed.data);};`, resolveDir: process.cwd() },
  bundle: true, platform: 'browser', format: 'iife', outfile: 'bundle.js',
});
const browser = await chromium.launch({ args: ['--no-sandbox', '--disable-dev-shm-usage'] });
const observations = { browser_version: browser.version(), input: input.csv, expected: input.expected };
try {
  const page = await browser.newPage({ viewport: { width: 900, height: 600 } });
  await page.setContent('<!doctype html><html lang="en"><title>Customer CSV import</title><body><h1>Import customers</h1><label>CSV data<textarea aria-label="CSV data" rows="8" cols="60"></textarea></label><br><button>Import</button><pre aria-label="Imported customers"></pre></body></html>');
  await page.addScriptTag({ path: 'bundle.js' });
  await page.getByRole('textbox', { name: 'CSV data' }).fill(input.csv);
  await page.getByRole('button', { name: 'Import' }).click();
  observations.actual = JSON.parse(await page.getByLabel('Imported customers').textContent());
  await page.screenshot({ path: `${process.env.EVALUATION_ARTIFACTS}/csv-browser.png`, fullPage: true });
  assert.deepEqual(observations.actual, input.expected);
} finally {
  await browser.close();
  await writeFile(process.env.EVALUATION_RESULTS, JSON.stringify(observations, null, 2));
}
